import React, { useEffect, useRef } from "react";
import { Close, Search } from "@airbus/icons/react";
import useControlled from "../../lib/hooks/useControlled";
import { useTheme } from "../../lib/styling";
import useMediaQuery from "../../lib/hooks/useMediaQuery";
import { BreakpointName } from "../helperTypes";
import IconButton, { IconButtonProps } from "../IconButton";
import Input from "./Input";
import { CommonProps } from "../helperTypes";

type Props = {
  /**
   * Debounce duration (ms) before onChange callback fires (default 0)
   * @default 0
   */
  debounce?: number;
  /** The default value to be used for an uncontrolled component */
  defaultValue?: string;
  /** optional react ref to pass to native input */
  inputRef?: React.RefObject<HTMLInputElement>;
  /** apply large size until given breakpoint, if size is not provided
   * @default xs
   */
  largeUntil?: BreakpointName;
  /**
   * Called each time the input value changes or when cleared.<br />
   * Use this if you want the search to be submitted live on each letter typed.
   */
  onChange?: (event: React.SyntheticEvent<any>, value: any) => void;
  /**
   * Called when user press enter key.<br />
   * Use this if you want the search to be submitted only on press of enter key.
   */
  onSearch?: (value: string) => void;
  endAdornment?: any;
  startAdornment?: any;
  /**
   * The size of the input
   * @default medium
   */
  size?: "xsmall" | "small" | "medium" | "large" | "xlarge";
  /** entered value */
  value?: string;
};

type SearchInputProps = Props & CommonProps;

const checkProps = ({ debounce = 0 }: Props) => {
  if (process.env.NODE_ENV === "production") return;

  if (debounce < 0) {
    console.warn(
      [
        "[AIRBUS-DS] The SearchInput expects the `debounce` prop to be greater than zero.",
        `However, "${debounce}" was provided. Default value of 0 will be used instead`,
      ].join("\n")
    );
  }
};

const SearchInput = (props: SearchInputProps) => {
  const {
    defaultValue = "",
    endAdornment,
    largeUntil = "xs",
    onChange,
    onSearch,
    size = "medium",
    startAdornment,
    value: valueProp,
    debounce = 0,
    ...rest
  } = props;
  useEffect(() => checkProps(props), [props]);
  const debounceTimer = useRef<NodeJS.Timeout | undefined>(undefined);

  // controlled / uncontrolled value
  const [value, setValue] = useControlled({
    value: valueProp,
    defaultValue: defaultValue,
  });

  // Determine clear button size based on input size
  const getClearButtonSize = (inputSize?: string) => {
    if (inputSize === "xsmall") return "xsmall";
    if (inputSize === "large" || inputSize === "xlarge") return "medium";
    return "small";
  };

  const ClearButton = (props: IconButtonProps) => (
    <IconButton
      variant="ghost"
      size={getClearButtonSize(size)}
      aria-label="clear"
      {...props}
    >
      <Close />
    </IconButton>
  );

  const handleChange = (
    evt: React.ChangeEvent<HTMLInputElement>,
    value: any
  ): void => {
    setValue(value);
    if (debounce > 0) {
      clearTimeout(debounceTimer?.current);

      debounceTimer.current = setTimeout(() => {
        handleOnChange(evt, value);
      }, debounce);

      return;
    }

    handleOnChange(evt, value);
  };
  const handleOnChange = (
    evt: React.ChangeEvent<HTMLInputElement>,
    value: any
  ) => {
    onChange && onChange(evt, value);
  };
  const handleKeyDown = (evt: React.KeyboardEvent<HTMLInputElement>): void => {
    if (evt.key !== "Enter") return;
    onSearch && onSearch(value);
  };
  const handleClear = (evt: React.MouseEvent<HTMLButtonElement>): void => {
    setValue("");
    onChange && onChange(evt, "");
  };
  const {
    responsive: { breakpoint },
  } = useTheme();
  const mqMatches = useMediaQuery(`(max-width: ${breakpoint[largeUntil]}px)`);
  const computedSize = size ? size : mqMatches ? "large" : "medium";

  return (
    <Input
      startAdornment={<Search />}
      endAdornment={value && <ClearButton onClick={handleClear} />}
      onChange={handleChange}
      onKeyDown={handleKeyDown}
      value={value}
      size={computedSize}
      {...rest}
    />
  );
};

export default SearchInput;
